        best = (torch.where(choose, current[0], best[0]),) + tuple(
            torch.where(mask, new, old)
            for new, old in zip(current[1:], best[1:])
        )
    _, code, lv2, lv3, negative, mantissa_code = best
    mantissa = mantissa_code.to(torch.bfloat16) / 4.0
    sign = torch.where(
        mantissa == 0,
        torch.zeros_like(mantissa),
        torch.where(negative, -torch.ones_like(mantissa), torch.ones_like(mantissa)),
    )
    return {
        "scale_factor": _decode_e6m2(code).to(torch.bfloat16),
        "scale_lv2": 1.0 + lv2.to(torch.bfloat16),
        "scale_lv3": 1.0 + lv3.to(torch.bfloat16),
        "sign": sign,
        "mant": mantissa,
    }


def _rms(values: torch.Tensor) -> torch.Tensor:
    return values.to(torch.float32).reshape(-1, values.shape[-1]).square().mean(0).sqrt()


def _balanced_multiplier(left: torch.Tensor, right: torch.Tensor) -> torch.Tensor:
    tiny = torch.finfo(torch.float32).tiny
    multiplier = (right.clamp_min(tiny) / left.clamp_min(tiny)).sqrt()
    multiplier = multiplier.clamp(1.0 / 16.0, 16.0)
    return torch.where((left > 0) & (right > 0), multiplier, torch.ones_like(multiplier))


def _hadamard(values: torch.Tensor, block: int) -> torch.Tensor:
    result = values.to(torch.float32).reshape(-1, values.shape[-1] // block, block).clone()
    stride = 1
    while stride < block:
        pairs = result.reshape(*result.shape[:-1], block // (2 * stride), 2, stride)
        left = pairs[..., 0, :].clone()
        right = pairs[..., 1, :].clone()
        pairs[..., 0, :] = left + right
        pairs[..., 1, :] = left - right
        stride *= 2
    return (result / block**0.5).reshape_as(values)


def _sign_candidates() -> torch.Tensor:
    generator = torch.Generator().manual_seed(20260819)
    random = torch.randint(0, 2, (7, 64), generator=generator).to(torch.float32)
    return torch.cat((torch.ones(1, 64), random.mul_(2).sub_(1)))


def _peak_ratio(values: torch.Tensor) -> torch.Tensor:
    peak = values.abs().amax(-1).square().sum(0)
    energy = values.square().sum(dim=(0, 2))
    return peak / energy.clamp_min(torch.finfo(torch.float32).tiny)


def _select_linear_signs(activation: torch.Tensor, weight: torch.Tensor) -> torch.Tensor:
    group_count = activation.shape[-1] // 64
    a = activation.reshape(-1, group_count, 64)
    w = weight.reshape(-1, group_count, 64)
    candidates = _sign_candidates()
    scores = []
    for signs in candidates:
        scores.append(_peak_ratio(_hadamard(a * signs, 64)) + _peak_ratio(_hadamard(w * signs, 64)))
    return candidates[torch.stack(scores).argmin(0)].reshape(-1)


def _linear_transform(values: torch.Tensor, state: dict[str, Any]) -> torch.Tensor:
    values = values.to(torch.float32) * state["coefficient"]
    if state["hadamard"]:
        values = _hadamard(values, state["hadamard"])
    return values


@torch.inference_mode()
def hif4_calibration_and_quantize_weight(
    weight_quant: torch.Tensor,
    weight_scale: torch.Tensor,
    calib_activation_list: list,
) -> dict[str, Any]:
    weight = dequantize_nvfp4(weight_quant, weight_scale).to(torch.float32)
    activation = torch.cat(
        [dequantize_nvfp4(quant, scale).to(torch.float32) for quant, scale in calib_activation_list]
    )
    multiplier = _balanced_multiplier(_rms(activation), _rms(weight))
    transformed_activation = activation * multiplier
    transformed_weight = weight / multiplier
    coefficient = multiplier
    if _LINEAR_SIGN_SEARCH:
        signs = _select_linear_signs(transformed_activation, transformed_weight)
        coefficient = coefficient * signs
        transformed_activation = transformed_activation * signs
        transformed_weight = transformed_weight * signs
    if _LINEAR_HADAMARD:
        transformed_activation = _hadamard(transformed_activation, _LINEAR_HADAMARD)
        transformed_weight = _hadamard(transformed_weight, _LINEAR_HADAMARD)
    importance = transformed_activation.square().mean(0) if _WEIGHT_IMPORTANCE else None
    return {
        "weight_params": _quantize_values(transformed_weight, importance),
        "activation_state": {
            "version": 4,
            "coefficient": coefficient,
            "hadamard": _LINEAR_HADAMARD,
        },
    }


@torch.inference_mode()
def hif4_dynamic_quantize_activation(
    activation_quant: torch.Tensor,
    activation_scale: torch.Tensor,
    activation_state: Any,
) -> dict[str, torch.Tensor]:
    values = dequantize_nvfp4(activation_quant, activation_scale)
    return _quantize_values(_linear_transform(values, activation_state))


@torch.inference_mode()
def hif4_calibration_attention(
    calib_qkv_list: list,
    q_num_heads: int,
    kv_num_heads: int,
    head_dim: int,
) -> dict[str, Any]:
    q = torch.cat([dequantize_nvfp4(*sample["q"]).float() for sample in calib_qkv_list])
    k = torch.cat([dequantize_nvfp4(*sample["k"]).float() for sample in calib_qkv_list])
    replicas = q_num_heads // kv_num_heads
    q_heads = q.reshape(-1, q_num_heads, head_dim)
    k_heads = k.reshape(-1, kv_num_heads, head_dim)
    q_rms = q_heads.square().mean(0).sqrt()
    q_rms = q_rms.reshape(kv_num_heads, replicas, head_dim).mean(1)
    k_rms = k_heads.square().mean(0).sqrt()
    multiplier = _balanced_multiplier(q_rms, k_rms)
    block = head_dim if _QK_HADAMARD == -1 else _QK_HADAMARD
    return {
        "q_state": {
            "coefficient": multiplier.repeat_interleave(replicas, 0),
            "hadamard": block,
        },
        "k_state": {"coefficient": multiplier.reciprocal(), "hadamard": block},
        "v_state": {"coefficient": None, "hadamard": 0},
    }


def _dynamic_attention(
    quant: torch.Tensor,
    scale: torch.Tensor,
    heads: int,
    head_dim: int,
    state: Any,
) -> dict[str, torch.Tensor]:
    values = dequantize_nvfp4(quant, scale).to(torch.float32)
    if state["coefficient"] is not None:
        shaped = values.reshape(-1, heads, head_dim) * state["coefficient"].unsqueeze(0)
        if state["hadamard"]:
            shaped = _hadamard(shaped, state["hadamard"])
        values = shaped.reshape_as(values)
    return _quantize_values(values)


@torch.inference_mode()
def hif4_dynamic_quantize_q(q_quant, q_scale, q_num_heads, head_dim, q_state):
    return _dynamic_attention(q_quant, q_scale, q_num_heads, head_dim, q_state)


@torch.inference_mode()
def hif4_dynamic_quantize_k(k_quant, k_scale, kv_num_heads, head_dim, k_state):
    return _dynamic_attention(k_quant, k_scale, kv_num_heads, head_dim, k_state)


@torch.inference_mode()
def hif4_dynamic_quantize_v(v_quant, v_scale, kv_num_heads, head_dim, v_state):
    return _dynamic_attention(v_quant, v_scale, kv_num_heads, head_dim, v_state)

